const CACHE='little-stone-club-v1.2.0-research';
const FILES=['./','./index.html','./style.css','./game.js','./physics.js','./data.js','./art.js','./optimizer.js','./genetics.js','./quantum.js','./throw-search.js','./fluid-worker.js','./workshop.js','./research.css','./icon.svg','./synthesis.js','./audio-engine.js','./settings.js','./settings.css','./audio-lab.html','./audio-lab.js'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('little-stone-club-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request).then(c=>c||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
